function arrayEq(a, b) {
  var r;

  if (!Array.isArray(a) || !Array.isArray(b)) {
    return false;
  }

  if (a.length !== b.length) {
    return false;
  }

  r = true;

  detectRecursion(a, b, function () {
    var i, len;

    for (i = 0, len = a.length; i < len; i++) {
      if (!eq(a[i], b[i])) {
        r = false;break;
      }
    }
  });

  return r;
}

