		if ( !isObject( opts ) ) {
			throw new TypeError( 'iqr()::invalid input argument. Options should be an object.' );
		}
	} else {
		opts = {
			'sorted': false
		};
	}
	if ( !opts.sorted ) {
		arr = arr.slice();
		arr.sort( ascending );
		opts.sorted = true;
	}
	return quantile( arr, 0.75, opts ) - quantile( arr, 0.25, opts );
}

