function bsearch(arr, val, key) {
  var pred = typeof val === 'function' ? val : (typeof key === 'string'
    ? function(item) { return val <= item[key]; }
    : function(item) { return val <= item; });

  var lo = -1, hi = arr.length;
  while (1 + lo !== hi) {
    var mi = lo + ((hi - lo) >> 1);
    if (pred(arr[mi])) {
      hi = mi;
    } else {
      lo = mi;
    }
  }
  return hi;
}

