function findSourceFiles(pattern) {
  return pglob(pattern, { nodir: true })
    .then(files => {
      return files.map(file => {
        const ext = path.extname(file)
        const name = path.basename(file, ext)
        return {
          ext,
          name,
          fullname: `${name}${ext}`,
          path: file
        }
      })
    })
}

