function esc(str) {
	if(typeof(str) !== "string")
		str = "" + str;
	str = str.replace(/[\0\n\r\b\t\\\'\"\x1a]/g, function(res) {
		switch(res) {
			case "\0": return "\\0";
			case "\n": return "\\n";
			case "\r": return "\\r";
			case "\b": return "\\b";
			case "\t": return "\\t";
			case "\x1a": return "\\Z";
		default: return "\\"+res;
		}
	});
	return "'"+str+"'";
}

