    var projection = user.project('userinfo')
    var userInfo = { sub: projection.sub }

    scopeUserAttributes.forEach(function (key) {
      if (typeof projection[key] !== 'undefined') {
        userInfo[key] = projection[key]
      }
    })

    res.status(200).json(userInfo)
  })
}

