function eventLoop(control) {
        control = control || {};
        control.log = control.log || defaultLog;
        control.fail = control.fail || defaultFail;
        var count = control.count;
        while ((count === undefined) || (--count >= 0)) {
            var effect = options.stepping.dispatch();
            control.log(effect);  // log event
            if (effect === false) {
                return true;  // event queue exhausted
            }
            if (effect.exception) {
                control.fail(effect.exception);  // report exception
            }
        }
        return false;  // limit reached, events may remain
    }

