	const maxEnd = Math.max(fileStats.size - 1, 0);
	var start = headers.range.replace(/^bytes=/, '').match(/(-?[^-]+)(?:-(.+)|)/) || [];
	var end = Math.min(parseInt(start[1 + 1] || maxEnd, 10) || 0, maxEnd);

