function take(n) {
  var idx = 0;

  return map(function (chunk, next) {
    idx += 1;

    if (!_.isInteger(n)) {
      return next(new TypeError('Expected `n` to be an integer.'));
    }

    // take n items from the source stream
    if (idx <= n) {
      return next(null, chunk);
    }

    // drop all other items
    return next();
  });
}

