function isIntegerBuffer(buf) {
  var sign = '-'.charCodeAt(0)
    , i;

  // empty string is not an integer
  if(!buf.length) return false;

  for(i = 0;i < buf.length;i++) {
    if(!i && buf[i] === sign) continue;
    if(!~NUMBERS.indexOf(buf[i])) return false;
  }

  return true;
}

