      return function(x) {
         var res;

         if (isNaN(x)) { return NaN; }
         res = lowerTail === x < 0 ? -Infinity : 0;
         x = Math.floor(x);
         if (x >= 0 && x < size) {
            res = pbeta(x + 1, size - x, !lowerTail, true)(p);
         }

         return logp ? res : Math.exp(res);
      };
