function getUint32(buffer, offset, littleEndian) {
    var a;
    var b;
    var c;
    var d;
    if (littleEndian) {
        a = buffer[offset];
        b = buffer[offset + 1];
        c = buffer[offset + 2];
        d = buffer[offset + 3];
